+static void hci_restart_advertising(void)
+{
+  FAR struct bt_buf_s *cmd;
+  uint8_t enable;
+  int ret;
+
+  /* A connectable advertiser is normally stopped by the controller when a
+   * connection is accepted.  Restore it after every completed attempt, even
+   * if the host no longer has a matching connection object (for example when
+   * the central cancels during connection establishment).
+   */
+
+  if (!g_btdev.adv_enable)
+    {
+      return;
+    }
+
+  cmd = bt_hci_cmd_create(BT_HCI_OP_LE_SET_ADV_ENABLE, 1);
+  if (!cmd)
+    {
+      wlerr("ERROR: Failed to allocate advertising restart command\n");
+      return;
+    }
+
+  enable = 1;
+  memcpy(bt_buf_extend(cmd, 1), &enable, 1);
+  ret = bt_hci_cmd_send(BT_HCI_OP_LE_SET_ADV_ENABLE, cmd);
+  if (ret < 0)
+    {
+      wlerr("ERROR: Failed to queue advertising restart: %d\n", ret);
+    }
+}
+
+static void hci_disconn_complete(FAR struct bt_buf_s *buf)
 {
   FAR struct bt_hci_evt_disconn_complete_s *evt = (FAR void *)buf->data;
   uint16_t handle = BT_LE162HOST(evt->handle);
@@
   if (evt->status)
     {
       return;
     }
+
+  /* Do this before looking up the host connection.  The radio has already
+   * finished the link teardown, and advertising must not depend on whether
+   * the host-side connection object survived the teardown race.
+   */
+
+  hci_restart_advertising();

   conn = bt_conn_lookup_handle(handle);
   if (!conn)
@@

